function grOut(bool $ok,string $message='',array $data=[],int $status=200):never{
    while(ob_get_level()>0)ob_end_clean();
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    echo json_encode(['success'=>$ok,'message'=>$message,'data'=>$data],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    exit;
}
function grInput():array{$d=json_decode((string)file_get_contents('php://input'),true);return is_array($d)?$d:$_POST;}
function grScope():array{$u=function_exists('current_user')?current_user():[];return['tenant_id'=>(int)($u['tenant_id']??$u['school_id']??$_SESSION['tenant_id']??0),'branch_id'=>(int)($u['branch_id']??$_SESSION['branch_id']??0),'user_id'=>(int)($u['id']??$u['user_id']??$_SESSION['user_id']??0),'role'=>(string)($u['role_name']??$u['role']??$_SESSION['role_name']??$_SESSION['role']??'')];}
function grCsrf(array $i):void{$s=(string)($_SESSION['grades_csrf_token']??'');$r=(string)($i['csrf_token']??'');if($s===''||$r===''||!hash_equals($s,$r))grOut(false,'Invalid or expired CSRF token. Refresh the page.',[],419);}
function grCan(array $s,string $action):bool{
    $role=strtolower(trim((string)$s['role']));
    if(in_array($role,['super_admin','super administrator','super admin','administrator','admin','school_admin','school admin','schooladmin','principal','teacher'],true))return true;
    if(function_exists('has_permission')){
        foreach(['grades_management','grade_management','examination_management','academic_management'] as $key){
            try{if(has_permission($key,$action))return true;}catch(Throwable $e){error_log('grades permission: '.$e->getMessage());}
        }
    }
    return $action==='view';
}
function grExists(PDO $pdo,string $table):bool{$q=$pdo->prepare("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=:t");$q->execute(['t'=>$table]);return(int)$q->fetchColumn()>0;}
function grName(string $a='s'):string{return "TRIM(CONCAT(COALESCE($a.first_name,''),CASE WHEN COALESCE($a.last_name,'')='' THEN '' ELSE CONCAT(' ',$a.last_name) END))";}
function grEnsure(PDO $pdo):void{
    $pdo->exec("CREATE TABLE IF NOT EXISTS grade_systems(
      id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL,academic_year_id BIGINT UNSIGNED NULL,
      system_name VARCHAR(120) NOT NULL,calculation_type ENUM('percentage','marks','gpa') NOT NULL DEFAULT 'percentage',
      is_default TINYINT(1) NOT NULL DEFAULT 0,status ENUM('active','inactive') NOT NULL DEFAULT 'active',description VARCHAR(500) NULL,
      created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),
      UNIQUE KEY uq_grade_system(tenant_id,system_name,academic_year_id),KEY idx_grade_system(tenant_id,status)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $pdo->exec("CREATE TABLE IF NOT EXISTS grade_rules(
      id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL,grade_system_id BIGINT UNSIGNED NOT NULL,
      grade_name VARCHAR(20) NOT NULL,min_percentage DECIMAL(6,2) NOT NULL,max_percentage DECIMAL(6,2) NOT NULL,
      grade_point DECIMAL(5,2) NOT NULL DEFAULT 0,result_status ENUM('pass','fail') NOT NULL DEFAULT 'pass',remarks VARCHAR(255) NULL,
      display_order INT NOT NULL DEFAULT 0,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,
      updated_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      PRIMARY KEY(id),UNIQUE KEY uq_grade_rule(tenant_id,grade_system_id,grade_name),KEY idx_grade_rule_range(tenant_id,grade_system_id,status,min_percentage,max_percentage)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $pdo->exec("CREATE TABLE IF NOT EXISTS student_grades(
      id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,
      academic_year_id BIGINT UNSIGNED NOT NULL,academic_year_name VARCHAR(50) NOT NULL,class_id BIGINT UNSIGNED NOT NULL,
      class_name VARCHAR(150) NOT NULL,section_id BIGINT UNSIGNED NULL,section_name VARCHAR(100) NULL,student_id BIGINT UNSIGNED NOT NULL,
      student_name VARCHAR(220) NOT NULL,admission_no VARCHAR(50) NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,subject_name VARCHAR(150) NOT NULL,
      exam_name VARCHAR(120) NOT NULL,exam_date DATE NULL,grade_system_id BIGINT UNSIGNED NOT NULL,grade_rule_id BIGINT UNSIGNED NOT NULL,
      marks_obtained DECIMAL(10,2) NOT NULL,maximum_marks DECIMAL(10,2) NOT NULL,percentage DECIMAL(7,2) NOT NULL,
      grade_name VARCHAR(20) NOT NULL,grade_point DECIMAL(5,2) NOT NULL,result_status ENUM('pass','fail') NOT NULL,
      publish_status ENUM('draft','published') NOT NULL DEFAULT 'draft',published_by BIGINT UNSIGNED NULL,published_at DATETIME NULL,
      remarks VARCHAR(255) NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),
      UNIQUE KEY uq_student_grade(tenant_id,academic_year_id,student_id,subject_id,exam_name),
      KEY idx_student_grade_filter(tenant_id,branch_id,academic_year_id,class_id,section_id,publish_status),KEY idx_student_grade_student(tenant_id,student_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $pdo->exec("CREATE TABLE IF NOT EXISTS grade_audit_logs(
      id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,
      record_type VARCHAR(40) NOT NULL,record_id BIGINT UNSIGNED NULL,action_name VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NULL,
      record_label VARCHAR(180) NULL,details_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),
      KEY idx_grade_audit(tenant_id,created_at)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
function grSeed(PDO $pdo,array $s):void{
    $q=$pdo->prepare("SELECT id FROM grade_systems WHERE tenant_id=:t ORDER BY is_default DESC,id LIMIT 1");$q->execute(['t'=>$s['tenant_id']]);$system=(int)$q->fetchColumn();
    if($system<=0){
        $q=$pdo->prepare("INSERT INTO grade_systems(tenant_id,academic_year_id,system_name,calculation_type,is_default,status,description,created_by,updated_by) VALUES(:t,NULL,'Standard Percentage Grading','percentage',1,'active','Default percentage based grading system',:u,:u2)");$q->execute(['t'=>$s['tenant_id'],'u'=>$s['user_id']?:null,'u2'=>$s['user_id']?:null]);$system=(int)$pdo->lastInsertId();
    }
    $rules=[['A+',90,100,10,'pass','Outstanding'],['A',80,89.99,9,'pass','Excellent'],['B+',70,79.99,8,'pass','Very Good'],['B',60,69.99,7,'pass','Good'],['C',50,59.99,6,'pass','Satisfactory'],['D',35,49.99,5,'pass','Pass'],['F',0,34.99,0,'fail','Needs Improvement']];
    $q=$pdo->prepare("INSERT INTO grade_rules(tenant_id,grade_system_id,grade_name,min_percentage,max_percentage,grade_point,result_status,remarks,display_order,status,created_by,updated_by) VALUES(:t,:s,:g,:mn,:mx,:gp,:rs,:r,:o,'active',:u,:u2) ON DUPLICATE KEY UPDATE min_percentage=VALUES(min_percentage),max_percentage=VALUES(max_percentage),grade_point=VALUES(grade_point),result_status=VALUES(result_status),remarks=VALUES(remarks),status='active'");
    foreach($rules as $idx=>$r)$q->execute(['t'=>$s['tenant_id'],'s'=>$system,'g'=>$r[0],'mn'=>$r[1],'mx'=>$r[2],'gp'=>$r[3],'rs'=>$r[4],'r'=>$r[5],'o'=>$idx+1,'u'=>$s['user_id']?:null,'u2'=>$s['user_id']?:null]);
}
function grAudit(PDO $pdo,array $s,string $type,?int $id,string $action,string $label,array $details=[]):void{$q=$pdo->prepare("INSERT INTO grade_audit_logs(tenant_id,branch_id,record_type,record_id,action_name,user_id,record_label,details_json) VALUES(:t,:b,:rt,:id,:a,:u,:l,:d)");$q->execute(['t'=>$s['tenant_id'],'b'=>$s['branch_id']?:null,'rt'=>$type,'id'=>$id,'a'=>$action,'u'=>$s['user_id']?:null,'l'=>substr($label,0,180),'d'=>json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}
function grMeta(PDO $pdo,array $s):array{
    $q=$pdo->prepare("SELECT id,year_name FROM academic_years WHERE tenant_id=:t ORDER BY is_current DESC,id DESC");$q->execute(['t'=>$s['tenant_id']]);$years=$q->fetchAll(PDO::FETCH_ASSOC);
    $classes=[];
    if(grExists($pdo,'class_management_classes')){$q=$pdo->prepare("SELECT id,academic_year_id,class_name,section_name,CONCAT(class_name,' - ',section_name) class_label FROM class_management_classes WHERE tenant_id=:t AND status='active' ORDER BY display_order,class_name,section_name");$q->execute(['t'=>$s['tenant_id']]);$classes=$q->fetchAll(PDO::FETCH_ASSOC);}
    if(!$classes&&grExists($pdo,'classes')){$q=$pdo->prepare("SELECT id,academic_year_id,class_name,class_name class_label FROM classes WHERE tenant_id=:t AND status='active' ORDER BY display_order,class_name");$q->execute(['t'=>$s['tenant_id']]);$classes=$q->fetchAll(PDO::FETCH_ASSOC);}
    $sections=[];
    if(grExists($pdo,'school_sections')){$q=$pdo->prepare("SELECT id,class_id,academic_year_id,section_name,CONCAT(class_name_snapshot,' - ',section_name) section_label FROM school_sections WHERE tenant_id=:t AND status='active' ORDER BY display_order,section_name");$q->execute(['t'=>$s['tenant_id']]);$sections=$q->fetchAll(PDO::FETCH_ASSOC);}
    if(!$sections&&grExists($pdo,'sections')){$q=$pdo->prepare("SELECT id,class_id,NULL academic_year_id,section_name,section_name section_label FROM sections WHERE tenant_id=:t AND status='active' ORDER BY section_name");$q->execute(['t'=>$s['tenant_id']]);$sections=$q->fetchAll(PDO::FETCH_ASSOC);}
    $subjects=[];
    if(grExists($pdo,'school_subjects')){$q=$pdo->prepare("SELECT id,academic_year_id,subject_name,subject_code,maximum_marks,pass_marks FROM school_subjects WHERE tenant_id=:t AND status='active' ORDER BY display_order,subject_name");$q->execute(['t'=>$s['tenant_id']]);$subjects=$q->fetchAll(PDO::FETCH_ASSOC);}
    if(!$subjects&&grExists($pdo,'subjects')){$q=$pdo->prepare("SELECT id,NULL academic_year_id,subject_name,subject_code,100 maximum_marks,35 pass_marks FROM subjects WHERE tenant_id=:t AND status='active' ORDER BY subject_name");$q->execute(['t'=>$s['tenant_id']]);$subjects=$q->fetchAll(PDO::FETCH_ASSOC);}
    $students=[];
    if(grExists($pdo,'student_enrollments')){$q=$pdo->prepare("SELECT st.id,CONCAT(".grName('st').",' (',st.admission_no,')') student_label,".grName('st')." student_name,st.admission_no,se.academic_year_id,se.class_id,se.section_id FROM students st LEFT JOIN student_enrollments se ON se.student_id=st.id AND se.tenant_id=st.tenant_id AND se.enrollment_status='active' WHERE st.tenant_id=:t AND (:bs=0 OR st.branch_id=:b) AND st.status='active' AND st.deleted_at IS NULL ORDER BY st.first_name,st.last_name");$q->execute(['t'=>$s['tenant_id'],'bs'=>$s['branch_id'],'b'=>$s['branch_id']]);$students=$q->fetchAll(PDO::FETCH_ASSOC);}else{$q=$pdo->prepare("SELECT st.id,CONCAT(".grName('st').",' (',st.admission_no,')') student_label,".grName('st')." student_name,st.admission_no,NULL academic_year_id,NULL class_id,NULL section_id FROM students st WHERE st.tenant_id=:t AND (:bs=0 OR st.branch_id=:b) AND st.status='active' AND st.deleted_at IS NULL ORDER BY st.first_name,st.last_name");$q->execute(['t'=>$s['tenant_id'],'bs'=>$s['branch_id'],'b'=>$s['branch_id']]);$students=$q->fetchAll(PDO::FETCH_ASSOC);}
    $q=$pdo->prepare("SELECT gs.*,ay.year_name,(SELECT COUNT(*) FROM grade_rules r WHERE r.grade_system_id=gs.id AND r.tenant_id=gs.tenant_id) rule_count FROM grade_systems gs LEFT JOIN academic_years ay ON ay.id=gs.academic_year_id WHERE gs.tenant_id=:t ORDER BY gs.is_default DESC,gs.system_name");$q->execute(['t'=>$s['tenant_id']]);$systems=$q->fetchAll(PDO::FETCH_ASSOC);
    return compact('years','classes','sections','subjects','students','systems');
}
function grWhere(array $s,array $f,array &$p):array{$where=['g.tenant_id=:t','(:bs=0 OR g.branch_id=:b)'];$p=['t'=>$s['tenant_id'],'bs'=>$s['branch_id'],'b'=>$s['branch_id']];$search=trim((string)($f['search']??''));if($search!==''){$where[]='(g.student_name LIKE :q OR g.admission_no LIKE :q OR g.exam_name LIKE :q OR g.subject_name LIKE :q)';$p['q']='%'.$search.'%';}foreach(['academic_year_id'=>'y','class_id'=>'c','section_id'=>'sec','subject_id'=>'sub'] as $field=>$param){if(!empty($f[$field])&&$f[$field]!=='all'){$where[]="g.$field=:$param";$p[$param]=(int)$f[$field];}}if(!empty($f['publish_status'])&&$f['publish_status']!=='all'){$where[]='g.publish_status=:ps';$p['ps']=$f['publish_status'];}return$where;}
function grRows(PDO $pdo,array $s,array $f,int $page,int $per):array{$p=[];$where=grWhere($s,$f,$p);$q=$pdo->prepare("SELECT COUNT(*) FROM student_grades g WHERE ".implode(' AND ',$where));$q->execute($p);$total=(int)$q->fetchColumn();$last=max(1,(int)ceil($total/$per));$page=min(max(1,$page),$last);$offset=($page-1)*$per;$userJoin='';$userSelect='NULL created_by_name';if(grExists($pdo,'users')){$userJoin=' LEFT JOIN users u ON u.id=g.created_by ';$userSelect="COALESCE(u.name,u.username,u.email,'-') created_by_name";}$q=$pdo->prepare("SELECT g.*,$userSelect FROM student_grades g $userJoin WHERE ".implode(' AND ',$where)." ORDER BY g.exam_date DESC,g.id DESC LIMIT {$per} OFFSET {$offset}");$q->execute($p);$rows=$q->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $idx=>&$r)$r['row_number']=$offset+$idx+1;return['records'=>$rows,'pagination'=>['total'=>$total,'page'=>$page,'per_page'=>$per,'last_page'=>$last]];}
function grStats(PDO $pdo,array $s):array{$q=$pdo->prepare("SELECT (SELECT COUNT(*) FROM grade_systems WHERE tenant_id=:t1) total_systems,(SELECT COUNT(*) FROM grade_rules WHERE tenant_id=:t2 AND status='active') active_rules,(SELECT COUNT(DISTINCT student_id) FROM student_grades WHERE tenant_id=:t3 AND (:bs=0 OR branch_id=:b)) students_evaluated,(SELECT COUNT(*) FROM student_grades WHERE tenant_id=:t4 AND (:bs2=0 OR branch_id=:b2) AND publish_status='published') published_results");$q->execute(['t1'=>$s['tenant_id'],'t2'=>$s['tenant_id'],'t3'=>$s['tenant_id'],'bs'=>$s['branch_id'],'b'=>$s['branch_id'],'t4'=>$s['tenant_id'],'bs2'=>$s['branch_id'],'b2'=>$s['branch_id']]);return$q->fetch(PDO::FETCH_ASSOC)?:[];}
function grRules(PDO $pdo,array $s):array{$q=$pdo->prepare("SELECT r.*,gs.system_name FROM grade_rules r INNER JOIN grade_systems gs ON gs.id=r.grade_system_id WHERE r.tenant_id=:t ORDER BY gs.system_name,r.display_order,r.max_percentage DESC");$q->execute(['t'=>$s['tenant_id']]);return$q->fetchAll(PDO::FETCH_ASSOC);}
function grSummary(PDO $pdo,array $s):array{$q=$pdo->prepare("SELECT grade_name,COUNT(*) students,SUM(result_status='pass') passed,SUM(result_status='fail') failed,ROUND(AVG(percentage),2) average_percentage,SUM(publish_status='published') published FROM student_grades WHERE tenant_id=:t AND (:bs=0 OR branch_id=:b) GROUP BY grade_name ORDER BY MAX(percentage) DESC");$q->execute(['t'=>$s['tenant_id'],'bs'=>$s['branch_id'],'b'=>$s['branch_id']]);return$q->fetchAll(PDO::FETCH_ASSOC);}
function grHistory(PDO $pdo,array $s):array{$userJoin='';$userSelect='NULL user_name';if(grExists($pdo,'users')){$userJoin=' LEFT JOIN users u ON u.id=a.user_id ';$userSelect="COALESCE(u.name,u.username,u.email,'-') user_name";}$q=$pdo->prepare("SELECT a.created_at,a.action_name,a.record_label,$userSelect,LEFT(REPLACE(REPLACE(COALESCE(a.details_json,''),CHAR(10),' '),CHAR(13),' '),300) details_text FROM grade_audit_logs a $userJoin WHERE a.tenant_id=:t ORDER BY a.id DESC LIMIT 100");$q->execute(['t'=>$s['tenant_id']]);return$q->fetchAll(PDO::FETCH_ASSOC);}
function grLookup(PDO $pdo,array $s,string $type,int $id):array{
    if($type==='year'){$q=$pdo->prepare("SELECT id,year_name label FROM academic_years WHERE id=:id AND tenant_id=:t");}
    elseif($type==='class'&&grExists($pdo,'class_management_classes')){$q=$pdo->prepare("SELECT id,class_name label,section_name extra FROM class_management_classes WHERE id=:id AND tenant_id=:t");}
    elseif($type==='class'){$q=$pdo->prepare("SELECT id,class_name label,NULL extra FROM classes WHERE id=:id AND tenant_id=:t");}
    elseif($type==='section'&&grExists($pdo,'school_sections')){$q=$pdo->prepare("SELECT id,section_name label,NULL extra FROM school_sections WHERE id=:id AND tenant_id=:t");}
    elseif($type==='section'){$q=$pdo->prepare("SELECT id,section_name label,NULL extra FROM sections WHERE id=:id AND tenant_id=:t");}
    elseif($type==='subject'&&grExists($pdo,'school_subjects')){$q=$pdo->prepare("SELECT id,subject_name label,NULL extra FROM school_subjects WHERE id=:id AND tenant_id=:t");}
    elseif($type==='subject'){$q=$pdo->prepare("SELECT id,subject_name label,NULL extra FROM subjects WHERE id=:id AND tenant_id=:t");}
    elseif($type==='student'){$q=$pdo->prepare("SELECT id,".grName('students')." label,admission_no extra FROM students WHERE id=:id AND tenant_id=:t AND deleted_at IS NULL");}
    else throw new InvalidArgumentException('Invalid reference lookup.');
    $q->execute(['id'=>$id,'t'=>$s['tenant_id']]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new InvalidArgumentException('Selected reference record is unavailable.');return$r;
}

if(!isset($pdo)||!$pdo instanceof PDO)grOut(false,'Database connection unavailable.',[],500);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
if(empty($_SESSION['grades_csrf_token']))$_SESSION['grades_csrf_token']=bin2hex(random_bytes(32));
$s=grScope();if($s['tenant_id']<=0||$s['user_id']<=0)grOut(false,'Tenant or user session is missing.',[],401);
grEnsure($pdo);grSeed($pdo,$s);$i=grInput();$action=strtolower(trim((string)($i['action']??$_GET['action']??'')));

try{
