    if($action==='save_system'){
        grCsrf($i);if(!grCan($s,'edit')&&!grCan($s,'create'))grOut(false,'You do not have permission to save grade systems.',[],403);
        $id=(int)($i['id']??0);$name=trim((string)($i['system_name']??''));$year=(int)($i['academic_year_id']??0);$calc=(string)($i['calculation_type']??'percentage');$status=(string)($i['status']??'active');$default=!empty($i['is_default'])?1:0;$description=trim((string)($i['description']??''));
        if($name==='')throw new InvalidArgumentException('Grade system name is required.');if(!in_array($calc,['percentage','marks','gpa'],true)||!in_array($status,['active','inactive'],true))throw new InvalidArgumentException('Invalid grade system values.');
        $pdo->beginTransaction();if($default)$pdo->prepare("UPDATE grade_systems SET is_default=0 WHERE tenant_id=:t")->execute(['t'=>$s['tenant_id']]);
        if($id>0){$q=$pdo->prepare("UPDATE grade_systems SET academic_year_id=:y,system_name=:n,calculation_type=:c,is_default=:d,status=:s,description=:ds,updated_by=:u WHERE id=:id AND tenant_id=:t");$q->execute(['y'=>$year?:null,'n'=>$name,'c'=>$calc,'d'=>$default,'s'=>$status,'ds'=>$description?:null,'u'=>$s['user_id'],'id'=>$id,'t'=>$s['tenant_id']]);if(!$q->rowCount()){$q=$pdo->prepare("SELECT id FROM grade_systems WHERE id=:id AND tenant_id=:t");$q->execute(['id'=>$id,'t'=>$s['tenant_id']]);if(!$q->fetchColumn())throw new InvalidArgumentException('Grade system not found.');}$message='Grade system updated successfully.';}else{$q=$pdo->prepare("INSERT INTO grade_systems(tenant_id,academic_year_id,system_name,calculation_type,is_default,status,description,created_by,updated_by) VALUES(:t,:y,:n,:c,:d,:s,:ds,:u,:u2)");$q->execute(['t'=>$s['tenant_id'],'y'=>$year?:null,'n'=>$name,'c'=>$calc,'d'=>$default,'s'=>$status,'ds'=>$description?:null,'u'=>$s['user_id'],'u2'=>$s['user_id']]);$id=(int)$pdo->lastInsertId();$message='Grade system created successfully.';}grAudit($pdo,$s,'system',$id,$id?'save_system':'create_system',$name,$i);$pdo->commit();grOut(true,$message,['id'=>$id]);
    }
    if($action==='delete_system'){
